"use strict";

// Standalone, offline HTML presentations of frozen calibration data.
const fs = require("node:fs");
const path = require("node:path");
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const json = value => JSON.stringify(value).replaceAll("<", "\\u003c");
const number = n => Number(n).toLocaleString("it-IT", { maximumFractionDigits: 1 });
const levelNames = { easy: "Easy", medium: "Medium", hard: "Hard", impossible: "Impossible" };
const badge = level => `<span class="level ${esc(level)}">${esc(levelNames[level] || level)}</span>`;

// Validate the entire import before touching saved work. Split ownership stays
// with the frozen template, including when restoring the older review page.
function mergeLabels(target, saved) {
  if (saved?.version !== 1 || saved.kind !== "recognition-human-labels"
      || saved.sampleDigest !== target.sampleDigest || saved.indexDigest !== target.indexDigest || !Array.isArray(saved.rows))
    throw Error("Il file appartiene a un altro campione.");
  const rows = new Map(target.rows.map(row => [row.id, row])), seen = new Set();
  for (const row of saved.rows) {
    if (!row || !rows.has(row.id) || seen.has(row.id)
        || (row.expectedLevel !== null && !["easy", "medium", "hard", "impossible"].includes(row.expectedLevel))
        || typeof row.notes !== "string") throw Error("Il file contiene valutazioni non valide o duplicate.");
    seen.add(row.id);
  }
  for (const row of saved.rows) {
    const existing = rows.get(row.id);
    existing.expectedLevel = row.expectedLevel;
    existing.notes = row.notes;
  }
}
