function fonts() {
  const directory = path.join(__dirname, "../site/fonts");
  return ["600-normal", "700-italic"].map(style => {
    const file = path.join(directory, `barlow-semi-condensed-latin-${style}.woff2`);
    if (!fs.existsSync(file)) return "";
    return `@font-face{font-family:Barlow;src:url(data:font/woff2;base64,${fs.readFileSync(file).toString("base64")}) format('woff2');font-weight:${style.startsWith("600") ? 600 : 700};font-style:${style.endsWith("italic") ? "italic" : "normal"};font-display:swap}`;
  }).join("");
}

